const app=document.querySelector<HTMLDivElement>('#app')!;
app.innerHTML=`<header class="topbar"><div class="brand"><div class="brand-mark">C</div><div>COMBAT ROBOT ARENA<br><small>BUILT TO COLLIDE</small></div></div><nav class="nav" aria-label="Main navigation"><button data-nav="menu" class="active">ARENA</button><button data-nav="builder">BUILDER</button><button data-nav="bracket">TOURNAMENT</button><button data-nav="online">ONLINE</button></nav><div class="top-actions"><span class="version">HEAVYWEIGHT / 113.398 KG</span><button class="settings-btn small" id="open-settings" aria-label="Open settings">Settings</button></div></header><main class="shell"><aside class="sidebar" id="sidebar"></aside><section class="arena-wrap" aria-label="3D robot arena"><div id="scene"></div><div id="arena-overlay"></div><div id="hud"></div></section><aside class="totals hidden" id="totals"></aside></main><footer class="rulebar"><span id="footer-left">ARENA-V1 &nbsp; / &nbsp; 3 MINUTES &nbsp; / &nbsp; PHYSICAL COMBAT</span><span id="footer-right">REFERENCE-INSPIRED MACHINES · CUSTOM GAME RULES</span></footer><div id="modals"></div><div class="narrow-message"><div><div class="eyebrow">DESKTOP CONTROLS</div><h2>A keyboard or gamepad is required.</h2><p>Open this game on a desktop with a wide screen. Use a keyboard or up to two gamepads.</p><p>Recommended window: 1280 × 720 or larger.</p><button id="dismiss-narrow" class="small">Browse menus anyway</button></div></div><div id="loading" class="loading"><div><div class="spinner"></div><div class="eyebrow">POWERING THE ARENA</div><h2>Preparing the machines</h2><p class="muted">Loading the local physics engine.</p></div></div>`;
