// Arrow keys move through menu buttons. Enter and Space activate the focused item.
document.addEventListener('keydown',event=>{
 if(!['menu','builder','settings','bracket','repair','result','paused'].includes(state)||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.code))return;
 const target=event.target;if(!(target instanceof HTMLButtonElement))return;
 const group=target.closest('.bot-options,.mode-switch,.difficulty,.nav,.modal,.sidebar');if(!group)return;
 const buttons=[...group.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')].filter(b=>!b.closest('.hidden'));
 const index=buttons.indexOf(target);if(index<0||buttons.length<2)return;
 event.preventDefault();const step=event.code==='ArrowUp'||event.code==='ArrowLeft'?-1:1;buttons[(index+step+buttons.length)%buttons.length].focus();
});
